// issue-002 的验收条件：数量升序，数量相同按仓库名升序。
// 用 unconfigured 里的仓库，保证断言与 config/thresholds.json 的具体配置无关。
func TestLowStockWarehousesOrderedByQuantityThenName(t *testing.T) {
	cases := []struct {
		name  string
		stock map[string]int
		want  []string
	}{
		{
			name:  "数量升序",
			stock: map[string]int{unconfigured[0]: 5, unconfigured[1]: 1},
			want:  []string{unconfigured[1], unconfigured[0]},
		},
		{
			name:  "数量相同时按仓库名升序",
			stock: map[string]int{unconfigured[1]: 3, unconfigured[0]: 3},
			want:  []string{unconfigured[0], unconfigured[1]},
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := LowStockWarehouses(tc.stock); !reflect.DeepEqual(got, tc.want) {
				t.Fatalf("LowStockWarehouses(%v) = %v, 期望 %v", tc.stock, got, tc.want)
			}
		})
	}
}

